const stockLossApplications = `-- name: StockLossApplications :many
SELECT id, source_year_id, target_tax_year, amount, created_at, updated_at FROM germany_stock_loss_applications WHERE source_year_id = ANY($1::uuid[])
`

func (q *Queries) StockLossApplications(ctx context.Context, ids []uuid.UUID) ([]GermanyStockLossApplication, error) {
	rows, err := q.db.Query(ctx, stockLossApplications, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []GermanyStockLossApplication{}
	for rows.Next() {
		var i GermanyStockLossApplication
		if err := rows.Scan(
			&i.ID,
			&i.SourceYearID,
			&i.TargetTaxYear,
			&i.Amount,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

